import {SphereWebGLRenderer} from '../../src/rendering/spherical-webgl.ts';import {sphericalFieldRaster} from '../../src/rendering/spherical-field-raster.ts';import {settledRasterBudget} from '../../src/rendering/raster-quality.ts';
export async function cutGlobeCurrentOutputProof(backend:'cpu'|'webgl2'){
 const path='/tests/fixtures/crescent-cut-globe-observer.ts',{current,canvas,view,renderCurrentGPU}=await import(path) as typeof import('./crescent-cut-globe-observer.ts');
 const s=current(),c=canvas(),r=c.getBoundingClientRect(),size={width:r.width,height:r.height},v=view(),appearance=JSON.parse(c.dataset.displayDiagnostics!).appearance,copy=document.createElement('canvas');copy.width=c.width;copy.height=c.height;let actual:Uint8ClampedArray,currentPng:string,freshPng:string,expected:Uint8ClampedArray;
 const read=(node:HTMLCanvasElement)=>{const gl=node.getContext('webgl2')!,raw=new Uint8Array(node.width*node.height*4),out=new Uint8ClampedArray(raw.length);gl.readPixels(0,0,node.width,node.height,gl.RGBA,gl.UNSIGNED_BYTE,raw);for(let y=0;y<node.height;y++)out.set(raw.subarray((node.height-y-1)*node.width*4,(node.height-y)*node.width*4),y*node.width*4);return out;};
 if(backend==='webgl2'){renderCurrentGPU();const gpu=document.querySelector<HTMLCanvasElement>('.sphere-gpu')!;actual=read(gpu);currentPng=gpu.toDataURL();const fresh=new SphereWebGLRenderer(copy,s.cache.elevationField!,()=>{});try{fresh.present(v,size,appearance);if(!fresh.available)throw Error(fresh.statistics.reason);expected=read(copy);freshPng=copy.toDataURL();}finally{fresh.dispose();}}
 else{const ctx=copy.getContext('2d')!;actual=c.getContext('2d')!.getImageData(0,0,c.width,c.height).data;currentPng=c.toDataURL();const steps=sphericalFieldRaster(s.cache.elevationField!.snapshot(),v,size,appearance,settledRasterBudget(size,devicePixelRatio,matchMedia('(pointer: coarse)').matches));let result=steps.next(),at=performance.now();while(!result.done){result=steps.next();if(performance.now()-at>5){await new Promise(resolve=>setTimeout(resolve,0));at=performance.now();}}const image=result.value,scratch=document.createElement('canvas');scratch.width=image.columns;scratch.height=image.rows;scratch.getContext('2d')!.putImageData(new ImageData(image.pixels as Uint8ClampedArray<ArrayBuffer>,image.columns,image.rows),0,0);ctx.setTransform(copy.width/size.width,0,0,copy.height/size.height,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(scratch,image.left,image.top,image.width,image.height);expected=ctx.getImageData(0,0,copy.width,copy.height).data;freshPng=copy.toDataURL();}
 let maxDifference=0,alphaDifferent=0,different=0;for(let i=0;i<actual.length;i++){const d=Math.abs(actual[i]!-expected[i]!);maxDifference=Math.max(maxDifference,d);if(d)different++;if(i%4===3&&d)alphaDifferent++;}return{backend,maxDifference,alphaDifferent,different,currentPng,freshPng};
}
